using System;using System.IO;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Windows.Forms;
namespace CircuitoStudio {
public sealed class ReturnSizingForm:Form {
Project project;Circuit circuit;ReturnSizingRequirements requirements;List<Action> readers=new List<Action>();List<ReturnConductorRating> library=new List<ReturnConductorRating>();List<ReturnSizingEvaluation> evaluated=new List<ReturnSizingEvaluation>();ReturnConductorRating neutral,protective;ListBox choices=new ListBox{Dock=DockStyle.Fill};ComboBox role=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=110};TextBox details=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Bottom,Height=260};public bool Changed{get;private set;}
public ReturnSizingForm(Project p,Circuit c){project=p;circuit=c;var old=c.ReturnSizing;requirements=old==null?new ReturnSizingRequirements():old.Requirements.Copy();neutral=old==null||old.Neutral==null?null:old.Neutral.Copy();protective=old==null||old.Protective==null?null:old.Protective.Copy();if(neutral!=null)library.Add(neutral.Copy());if(protective!=null)library.Add(protective.Copy());Text="Neutro, PE e PEN — "+c.Id;Size=new Size(1380,850);MinimumSize=new Size(1120,700);Font=new Font("Segoe UI",10);var split=new SplitContainer{Dock=DockStyle.Fill};split.Size=new Size(1320,700);split.SplitterDistance=545;split.Panel1.Controls.Add(TypedFields.Create(requirements,readers));split.Panel1.Controls.Add(new Label{Text="Requisitos e dados rastreáveis (rolar para os demais campos)",Dock=DockStyle.Top,Height=32});var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=94};role.FormattingEnabled=true;role.Format+=(sender,e)=>e.Value=TypedFields.Friendly(e.ListItem);role.Items.AddRange(new object[]{ReturnRole.Neutral,ReturnRole.PE,ReturnRole.PEN});role.SelectedIndex=0;bar.Controls.Add(role);Add(bar,"Importar CSV",Import);Add(bar,"Modelo vazio",()=>ExportTemplate());Add(bar,"Avaliar",EvaluateRows);Add(bar,"Menor seção válida",Recommend);Add(bar,"Guardar candidato",SelectCandidate);Add(bar,"Aplicar seleção",ApplySelection);Add(bar,"Remover seleção",()=>{circuit.ReturnSizing=null;Changed=true;neutral=protective=null;details.Text="Seleção removida; cabo de fase e condutores tipados preservados.";});split.Panel2.Controls.Add(choices);split.Panel2.Controls.Add(details);split.Panel2.Controls.Add(bar);Controls.Add(split);choices.SelectedIndexChanged+=(s,e)=>{if(choices.SelectedIndex>=0&&choices.SelectedIndex<evaluated.Count)details.Text=evaluated[choices.SelectedIndex].Detail;};details.Text="Importe condutores com fonte/versão/condições e preencha os requisitos. Avaliação não presume corrente neutra nula por balanceamento. Mesma matéria, um condutor por função; sem paralelos. R/X vazios são desconhecidos. Escolha explícita da regra/edição/hipóteses; não há declaração automática de conformidade IEC/NBR. Assinatura atual da proteção para vincular a documentação: "+ReturnSizing.ProtectionContext(c)+"\r\nNeutro salvo: "+(neutral==null?"nenhum":neutral.Reference)+"; PE/PEN salvo: "+(protective==null?"nenhum":protective.Reference)+".";}
void Add(Control parent,string text,Action action){var b=new Button{Text=text,AutoSize=true,Height=32};b.Click+=(s,e)=>{try{action();}catch(Exception ex){details.Text="Nenhuma alteração no projeto: "+ex.Message;}};parent.Controls.Add(b);}
void Read(){foreach(var read in readers)read();requirements.Validate();}
void Import(){using(var d=new OpenFileDialog{Filter="Condutores CSV|*.csv"})if(d.ShowDialog(this)==DialogResult.OK){var imported=ReturnSizing.Import(d.FileName);library=imported;EvaluateRows();}}
void ExportTemplate(){using(var d=new SaveFileDialog{Filter="Condutores CSV|*.csv",FileName="condutores-retorno.csv"})if(d.ShowDialog(this)==DialogResult.OK)ReturnSizing.Export(new ReturnConductorRating[0],d.FileName);}
public void LoadLibrary(IEnumerable<ReturnConductorRating> rows){var copy=rows.Select(r=>r.Copy()).ToList();foreach(var r in copy)r.Validate();library=copy;}
public void EvaluateRows(){Read();evaluated=library.Where(r=>r.Role==(ReturnRole)role.SelectedItem).Select(r=>ReturnSizing.Evaluate(project,circuit,requirements,r)).ToList();choices.Items.Clear();foreach(var e in evaluated)choices.Items.Add(e.Rating.Reference+" / "+e.Rating.SectionMm2+" mm² / Iz "+e.Rating.CorrectedIzA+" A / "+e.Status);if(choices.Items.Count>0)choices.SelectedIndex=0;else details.Text="Nenhum candidato desta função na biblioteca.";}
void Recommend(){EvaluateRows();var recommendation=ReturnSizing.Recommend(project,circuit,requirements,library,(ReturnRole)role.SelectedItem);if(recommendation==null){details.Text="Nenhuma seção atende todos os critérios locais com dados completos. Consulte os candidatos e pendências.";return;}choices.SelectedIndex=evaluated.FindIndex(e=>Object.ReferenceEquals(e.Rating,recommendation.Rating));details.Text="Menor seção entre os candidatos válidos da biblioteca; sem otimização econômica global.\r\n"+recommendation.Detail;}
void SelectCandidate(){Read();if(choices.SelectedIndex<0)throw new InvalidDataException("Selecione um candidato avaliado.");var rating=evaluated[choices.SelectedIndex].Rating;var latest=ReturnSizing.Evaluate(project,circuit,requirements,rating);if(latest.Status=="Não atende")throw new InvalidDataException(latest.Detail);if(rating.Role==ReturnRole.Neutral){if(protective!=null&&protective.Role==ReturnRole.PEN)throw new InvalidDataException("Remova a seleção PEN antes de selecionar N separado.");neutral=rating.Copy();}else{protective=rating.Copy();if(rating.Role==ReturnRole.PEN)neutral=null;}details.Text="Candidato guardado na cópia; aplique para salvar no circuito.\r\n"+latest.Detail;}
public void ApplySelection(){Read();ReturnSizing.Apply(project,circuit,new ReturnSizingBinding{Engine=ReturnSizing.EngineId,Requirements=requirements,Neutral=neutral,Protective=protective});Changed=true;details.Text="Seleção salva.\r\n"+String.Join("\r\n",new[]{neutral,protective}.Where(r=>r!=null).Select(r=>ReturnSizing.Evaluate(project,circuit,requirements,r).Detail));}
}
partial class Studio {void ConfigureReturnSizing(){if(circuit==null)throw new InvalidOperationException("Selecione um circuito.");using(var form=new ReturnSizingForm(project,circuit)){form.ShowDialog(this);if(form.Changed)Change();}}}
}
